import { Logger } from './logger';
import * as fs from 'fs';
import * as path from 'path';
import * as vscode from 'vscode';
import {
  LanguageClient,
  LanguageClientOptions,
  ServerOptions,
  TransportKind,
} from 'vscode-languageclient/node';
import {
  SEND_TO_DEVTOOLS_ID,
  SEND_TO_GLASS_EASEL_LSP_SERVER_ID,
} from '../lib/constants';

class GlassEaselTemplateClient implements IExtensionCore {
  private glassEaselTemplateClient: LanguageClient | null = null;
  constructor(
    private readonly context: vscode.ExtensionContext,
    private readonly logger: Logger
  ) {
  }

  private sendToDevtools(params: ISendToDevtoolsParams): void {
    vscode.commands.executeCommand(SEND_TO_DEVTOOLS_ID, params);
  }

  private sendToServer(params: ILSPNotificationData): void {
    this.onReady(() => {
      this.glassEaselTemplateClient?.sendNotification(SEND_TO_GLASS_EASEL_LSP_SERVER_ID, params);
    });
  }

  private onReady(fn: Function): void {
    this.glassEaselTemplateClient?.onReady().then(() => {
      fn();
    });
  }

  init(): void {
    this.sendToDevtools({
      command: 'getGlassEaselTemplateCompilerPath',
    });
    vscode.commands.registerCommand('wechatMiniprogramDevelopment.getGlassEaselTemplateCompilerPath', async (data: { glassEaselTemplateCompilerPath: string }) => {
      const { glassEaselTemplateCompilerPath } = data;
      this.logger?.log(`glassEaselTemplateCompilerPath: ${glassEaselTemplateCompilerPath}`);
      if (glassEaselTemplateCompilerPath !== '' && fs.existsSync(glassEaselTemplateCompilerPath)) {
        // init LSP client\server
        const serverModule = this.context.asAbsolutePath(path.join('glassEaselTemplateServer.js')); // in wechat devtools, there is not a 'out' folder

        const serverOptions: ServerOptions = {
          run: {
            module: serverModule,
            transport: TransportKind.ipc,
            options: {
              env: {
                GlassEaselTemplateCompilerPath: glassEaselTemplateCompilerPath
              },
            },
          },
          debug: {
            module: serverModule,
            transport: TransportKind.ipc,
            options: {
              env: {
                GlassEaselTemplateCompilerPath: glassEaselTemplateCompilerPath
              },
            },
          },
        };
        const clientOptions: LanguageClientOptions = {
          documentSelector: [{
            scheme: 'file',
            language: 'wxml',
            pattern: '**/*.wxml', // detect wxml
          }],
        };
        this.glassEaselTemplateClient = new LanguageClient(
          'glassEaselTemplateServer',
          'Glass Easel Template Server',
          serverOptions,
          clientOptions
        );
        this.glassEaselTemplateClient.start();
        this.onReady(() => {
          this.logger?.log('glassEaselTemplateLanguage server start');
          this.glassEaselTemplateClient?.onNotification(SEND_TO_GLASS_EASEL_LSP_SERVER_ID, (payload: ILSPNotificationData) => {
            this.logger?.log('received payload', payload);
            switch (payload.command) {
              case 'checkIsGlassEaselTemplateFile': {
                this.sendToDevtools(payload);
              }
            }
          });
        });
      }
    });
    vscode.commands.registerCommand('wechatMiniprogramDevelopment.checkIsGlassEaselTemplateFile', (result: { path: string, result: boolean }) => {
      this.sendToServer({
        command: 'checkIsGlassEaselTemplateFile',
        data: result,
      });
    });
  }

  dispose(): void {
    this.glassEaselTemplateClient?.stop();
  }
}

export {
  GlassEaselTemplateClient,
};
